        return {"status": "equal" if same else "different", "runIdEqual": ea.get("runId") == eb.get("runId"),
                "blobsAdded": len(set(eb["blobs"]) - set(ea["blobs"])), "blobsRemoved": len(set(ea["blobs"]) - set(eb["blobs"]))}
